/// <summary>
/// Extension class for CustCustomerV3Entity
/// </summary>
[ExtensionOf(tableStr(CustCustomerV3Entity))]
public final class METCustCustomerV3Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean ret;

        //CB503_CustomerNumbering, retreive custom customer numbering logic
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerV3Entity, CustTable))
        {
            CustTable   custTable = _dataSourceCtx.getBuffer();
            CustGroup   custGroup = CustGroup::find(custTable.CustGroup);

            if (custGroup.METEnableCustNumbering == NoYes::Yes)
            {
                METBusinessUnit         metBusinessUnit;
                CustCustomerV3Staging   staging;    

                select firstonly metBusinessUnit
                    where metBusinessUnit.BusinessName == this.METBusinessName
                        && metBusinessUnit.BusinessPrefix == this.METBusinessPrefix
                        && metBusinessUnit.StatePrefixStr == this.METStatePrefixStr;
                
                if (metBusinessUnit.RecId)
                {
                    //Bug 242939: CB393 - Manual DMF import of customer created an incorrect system customer account number - Start
                    NumberSequenceTable     numberseqTable      = NumberSequenceTable::find(metBusinessUnit.NumberSequenceId);
                    if (!numberseqTable.Manual)
                    {
                    //Bug 242939: CB393 - Manual DMF import of customer created an incorrect system customer account number - End
                        custTable.AccountNum = CustTable::metGetCustomerNumSeqRec(metBusinessUnit.RecId);

                        select firstonly staging
                        where staging.CustomerAccount == this.CustomerAccount;

                        if (staging.RecId)
                        {
                            ttsbegin;
                            staging.selectForUpdate(true);
                            staging.CustomerAccount = custTable.AccountNum;
                            staging.update();
                            ttscommit;
                        }
                    } 
                }
            }

        }
        
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerV3Entity, METBusinessUnit))
        {
            if (CustGroup::find(this.CustomerGroupId).METEnableCustNumbering == NoYes::No)
            {
                DataEntityDataSourceRuntimeContext addressDataSourceContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(CustCustomerV3Entity, METBusinessUnit));
                addressDataSourceContext.setDataSaved(true);
                addressDataSourceContext.setDatabaseOperation(DataEntityDatabaseOperation::None);
            }
        }
        ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerV3Entity, METIndustryKeyTable))
        {
            ret = true;
        }
        
        return ret;
    }

    /// <summary>
    /// CoC method for UpdateEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean ret;
    	
        ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerV3Entity, METIndustryKeyTable))
        {
            ret = true;
        }
    
        return ret;
    }

    /// <summary>
    /// Extending standard method
    /// </summary>
    /// <param name = "entityCtx">DataEntityRuntimeContext</param>
    /// <param name = "dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext entityCtx, DataEntityDataSourceRuntimeContext dataSourceCtx)
    {
        next mapEntityToDataSource(entityCtx, dataSourceCtx);
        
        //Check if desired data source context is available
        ///MPJ_3338_AMEXCustomerPaymentProcessing -Vpotula
        ///excrypting the amex card number.
        if (dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerV3Entity, METCustTable))
        {
            METCustTable metCustTable = dataSourceCtx.getBuffer();
            metCustTable.amexCardNumEdit(true, this.METAMEXCardNumber);
        }

        if (dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerV3Entity, CustTable))
        {
            CustTable custTable = dataSourceCtx.getBuffer();
            if (this.WarehouseId)
            {
                //CB503_CustomerNumbering, setting the warehouse id
                custTable.InventLocation = this.WarehouseId;
                custTable.InventSiteId = InventLocation::find(this.WarehouseId).InventSiteId;

                custTable.DefaultDimension = InventSite::changeDimension(custTable.DefaultDimension, custTable.InventSiteId);
            }
        }

    }

    /// <summary>
    /// CB503_CustomerNumbering
    /// Validating the Business unit, Busines Prefix and State prefix
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean validateWrite()
    {
        boolean         ret = true;
        NoYesId         enableCustomerNumbering = CustGroup::find(this.CustomerGroupId).METEnableCustNumbering == NoYes::Yes;
        CustTable       custTableLoc = CustTable::find(this.CustomerAccount);
        METBusinessUnit metBusinessUnit; 

        ret = next validateWrite();
        
        if(!custTableLoc && enableCustomerNumbering)
        {
            select firstonly metBusinessUnit
                where metBusinessUnit.BusinessName == this.METBusinessName
                    && metBusinessUnit.BusinessPrefix == this.METBusinessPrefix
                    && metBusinessUnit.StatePrefixStr == this.METStatePrefixStr;
            
            if (!metBusinessUnit.RecId)
            {
                ret = ret && checkFailed(strFmt("@MET:METBusinessCombinationCheck", this.METBusinessName, this.METBusinessPrefix, this.METStatePrefixStr));
            }
        }
        return ret;
    }

    /// <summary>
    /// A change tracking query used by DMF to determine what values have changed in the specified data sources since the last export.
    /// 26544 Kyriba Change tracking query DCP 10/06/2022
    /// </summary>
    /// <returns>A query that represents the data sources used by the entity.</returns>
    public static Query defaultCTQuery()
    {
        Query                   metQuery;
        QueryBuildDataSource    metCustTableQBDS; 

        metQuery = next defaultCTQuery();

        metCustTableQBDS= metQuery.dataSourceTable(tableNum(CustTable));

        if(metCustTableQBDS)
        {
            QueryBuildDataSource qbdMETCustTable = metCustTableQBDS.addDataSource(tableNum(METCustTable));
            qbdMETCustTable.joinMode(JoinMode::OuterJoin);
            qbdMETCustTable.addLink(fieldNum(CustTable, AccountNum), fieldNum(METCustTable, AccountNum));
        }
        return metQuery;
    }

/// <summary>
/// Populates the company chain description.
/// </summary>
/// <returns>Returns the company chain description</returns>
static server str getDescription()
{
    return CustCustomerV3Entity::getChainDescription(tableStr(CustCustomerV3Entity), identifierStr(CustTable), fieldStr(CustTable, CompanyChainId));
}

    /// <summary>
    /// Gets the company chain description. 
    /// </summary>
    /// <param name = "_viewName">Entity name</param>
    /// <param name = "_DataSourceParty">Datasource name</param>
    /// <param name = "_DataSourcePartyField">Datasource field name</param>
    /// <returns></returns>
    public static server str getChainDescription(TableName _viewName,
                                                        str _DataSourceParty,
                                                        str _DataSourcePartyField)
    {
        str expression = 'select top 1 description from smmbusrelchaingroup where chainid = ' +
        SysComputedColumn::returnField(_viewName,
        _DataSourceParty,
        _DataSourcePartyField);

        return expression;
    }

    /// <summary>
    /// Determines if the datsource should be skipped for data event change tracking.
    /// </summary>
    /// <param name = "_entity">The entity being tracked.</param>
    /// <param name = "_datasourceName">The datasource within the entity to track.</param>
    /// <param name = "_primaryTableId">The table ID of the datasource being tracked.</param>
    /// <returns>true if the datasource should be skipped; otherwise, false.</returns>
    public static boolean dataEventsShouldSkipDataSource(DictDataEntity _entity, str _datasourceName, tableid _primaryTableId)
    {
        if (_primaryTableId == tableNum(METBusinessUnit) || _primaryTableId == tableNum(METIndustryKeyTable))
        {
            return true;
        }

        return false;
    }
